lines = csv_data.strip().split('\n')
headers = lines[0].split(',')

# Encontrar índices de INSCRIPCION y conceptos
inscripcion_idx = headers.index('INSCRIPCION')

# Suma total
total = 0

for i in range(1, len(lines)):
    values = lines[i].split(',')
    
    # INSCRIPCION (siempre está en la misma posición)
    if len(values) > inscripcion_idx and values[inscripcion_idx].strip():
        try:
            total += float(values[inscripcion_idx].strip())
        except:
            pass
    
    # Buscar SEGURO y CUOTA por nombre en headers
    for j, header in enumerate(headers):
        if j < len(values) and values[j].strip():
            if 'SEGURO' in header.upper() or 'CUOTA' in header.upper():
                if header != 'INSCRIPCION':
                    try:
                        val = values[j].strip()
                        if val and val not in ['', '0']:
                            total += float(val)
                    except:
                        pass

print(f"TOTAL RECAUDADO EN EXCEL (SECUNDARIA2026): ${total:,.2f}")
print()
print("COMPARACION CON PROGRAMA:")
print("Programa dice: $2.058.000,00 en SECUNDARIA")
print()
if abs(total - 2058000) < 1000:
    print("✅ COINCIDE")
else:
    print(f"❌ DIFERENCIA: ${abs(total - 2058000):,.2f}")
    print(f"   Excel tiene ${total:,.2f}")
    print(f"   Programa dice ${2058000:,.2f}")
